import React, { useState } from 'react';
import { X, ArrowRight } from 'lucide-react';

export default function StudentDetailsModal({ isOpen, onClose, onProceed }) {
  const [formData, setFormData] = useState({
    fullName: '',
    mobileNumber: '',
    email: '',
    qualification: '',
    branch: '',
    currentYear: '',
    careerGoal: ''
  });

  if (!isOpen) return null;

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onProceed(formData);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl max-w-md w-full p-6 sm:p-8 space-y-6 relative shadow-2xl">
        <button
          onClick={onClose}
          className="absolute top-6 right-6 text-slate-400 hover:text-white p-1 rounded-lg transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        <div className="space-y-1">
          <span className="text-xs font-semibold uppercase tracking-wider text-emerald-400">Step 2 of 3</span>
          <h3 className="text-2xl font-bold text-white">Student Details</h3>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <input required type="text" name="fullName" placeholder="Full Name" value={formData.fullName} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <input required type="tel" name="mobileNumber" placeholder="Mobile Number" value={formData.mobileNumber} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none" />
            <input required type="email" name="email" placeholder="Email Address" value={formData.email} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <input required type="text" name="qualification" placeholder="Qualification (e.g. M.Tech)" value={formData.qualification} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none" />
            <input required type="text" name="branch" placeholder="Branch" value={formData.branch} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <input required type="text" name="currentYear" placeholder="Current Year" value={formData.currentYear} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none" />
            <input required type="text" name="careerGoal" placeholder="Career Goal" value={formData.careerGoal} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none" />
          </div>

          <button
            type="submit"
            className="w-full py-3.5 mt-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-bold flex items-center justify-center space-x-2 transition transform hover:-translate-y-0.5"
          >
            <span>Continue to Payment</span>
            <ArrowRight className="w-4 h-4" />
          </button>
        </form>
      </div>
    </div>
  );
}
